/* ---------- buildQrGeometry from the extension ---------- */

const n = (value: number) => Math.round(value * 1000) / 1000
function rect(x: number, y: number, w: number, h: number, [tl, tr, br, bl]: number[]): string {
  return (
    `M${n(x + tl)} ${n(y)}H${n(x + w - tr)}A${tr} ${tr} 0 0 1 ${n(x + w)} ${n(y + tr)}` +
    `V${n(y + h - br)}A${br} ${br} 0 0 1 ${n(x + w - br)} ${n(y + h)}` +
    `H${n(x + bl)}A${bl} ${bl} 0 0 1 ${n(x)} ${n(y + h - bl)}` +
    `V${n(y + tl)}A${tl} ${tl} 0 0 1 ${n(x + tl)} ${n(y)}Z`
  )
}
const circle = (cx: number, cy: number, r: number) =>
  `M${n(cx - r)} ${n(cy)}a${r} ${r} 0 1 0 ${n(r * 2)} 0a${r} ${r} 0 1 0 ${n(-r * 2)} 0Z`

function eyeRing(shape: EyeShape, x: number, y: number): string {
  if (shape === 'rounded')
    return rect(x, y, 7, 7, [2, 2, 2, 2]) + rect(x + 1, y + 1, 5, 5, [1.2, 1.2, 1.2, 1.2])
  if (shape === 'circle') return circle(x + 3.5, y + 3.5, 3.5) + circle(x + 3.5, y + 3.5, 2.5)
  if (shape === 'leaf')
    return rect(x, y, 7, 7, [3, 0, 3, 0]) + rect(x + 1, y + 1, 5, 5, [2, 0, 2, 0])
  return rect(x, y, 7, 7, [0, 0, 0, 0]) + rect(x + 1, y + 1, 5, 5, [0, 0, 0, 0])
}
function eyePupil(shape: EyeShape, x: number, y: number): string {
  if (shape === 'rounded') return rect(x + 2, y + 2, 3, 3, [0.9, 0.9, 0.9, 0.9])
  if (shape === 'circle') return circle(x + 3.5, y + 3.5, 1.5)
  if (shape === 'leaf') return rect(x + 2, y + 2, 3, 3, [1.5, 0, 1.5, 0])
  return rect(x + 2, y + 2, 3, 3, [0, 0, 0, 0])
}

export const MARGIN = 2

export function geometry(payload: string, style: Style) {
  const code = QRCode.create(payload, { errorCorrectionLevel: 'M' })
  const size = code.modules.size
  const data = code.modules.data
  const m = MARGIN
  const inFinder = (r: number, c: number) =>
    (r < 7 && c < 7) || (r < 7 && c >= size - 7) || (r >= size - 7 && c < 7)
  const dark = (r: number, c: number) =>
    r >= 0 && c >= 0 && r < size && c < size && data[r * size + c] !== 0 && !inFinder(r, c)

  let body = ''
  for (let r = 0; r < size; r += 1) {
    if (style.moduleShape === 'square') {
      let c = 0
      while (c < size) {
        if (!dark(r, c)) {
          c += 1
          continue
        }
        const start = c
        while (c < size && dark(r, c)) c += 1
        body += `M${start + m} ${r + m}h${c - start}v1h${start - c}Z`
      }
      continue
    }
    for (let c = 0; c < size; c += 1) {
      if (!dark(r, c)) continue
      const x = c + m
      const y = r + m
      if (style.moduleShape === 'dots') body += circle(x + 0.5, y + 0.5, 0.45)
      else if (style.moduleShape === 'rounded')
        body += rect(x + 0.08, y + 0.08, 0.84, 0.84, [0.3, 0.3, 0.3, 0.3])
      else {
        const up = dark(r - 1, c)
        const down = dark(r + 1, c)
        const left = dark(r, c - 1)
        const right = dark(r, c + 1)
        body += rect(x, y, 1, 1, [
          !up && !left ? 0.5 : 0,
          !up && !right ? 0.5 : 0,
          !down && !right ? 0.5 : 0,
          !down && !left ? 0.5 : 0,
        ])
      }
    }
  }
  const eyes = [
    [m, m],
    [size - 7 + m, m],
    [m, size - 7 + m],
  ].map(([x, y]) => ({
    ring: eyeRing(style.eyeShape, x, y),
    pupil: eyePupil(style.eyeShape, x, y),
  }))
  return { width: size + m * 2, body, eyes, version: code.version, size }
}

/** Dark modules as cells, for codes that build module by module. */
export function cells(payload: string) {
  const code = QRCode.create(payload, { errorCorrectionLevel: 'M' })
  const size = code.modules.size
  const dark: [number, number][] = []
  for (let r = 0; r < size; r += 1)
    for (let c = 0; c < size; c += 1) if (code.modules.data[r * size + c]) dark.push([c, r])
  return { size, dark }
}

